const activityBox=document.createElement('section');activityBox.className='compact-activities';activityBox.innerHTML='<nav class="activity-tabs" aria-label="활동 종류"><button data-activity="quiz"><strong>💡 오늘의 퀴즈</strong><span>직업·대학·교과를 알아봐요</span></button><button data-activity="donate"><strong>🥗 공동 도시락</strong><span>수확물을 함께 나눠요</span></button><button data-activity="story"><strong>🤝 협력 이야기</strong><span>우리 반의 공동 목표를 확인해요</span></button><button data-activity="work"><strong>🧑‍🌾 직업 활동</strong><span>내 역할로 마을을 도와요</span></button></nav><div id="compactQuiz"><span class="eyebrow">DAILY CAREER</span><h1>오늘의 직업 탐험</h1><p>하루 한 문제, 우리 마을을 연결하는 직업을 만나요.</p><button id="startCompactQuiz">퀴즈 시작</button></div></section>';
